def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}

    divider = next(
        v for v in colors
        if any(all(x == v for x in grid[r]) for r in range(h))
        and any(all(grid[r][c] == v for r in range(h)) for c in range(w))
    )
    background = max(
        (v for v in colors if v != divider),
        key=lambda v: sum(x == v for row in grid for x in row)
    )

    row_cuts = [r for r in range(h) if all(x == divider for x in grid[r])]
    col_cuts = [c for c in range(w) if all(grid[r][c] == divider for r in range(h))]

    def intervals(n, cuts):
        bounds = [-1] + cuts + [n]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    output = []
    for r0, r1 in intervals(h, row_cuts):
        out_row = []
        for c0, c1 in intervals(w, col_cuts):
            count = sum(
                grid[r][c] != background and grid[r][c] != divider
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            out_row.append(1 if count == 2 else background)
        output.append(out_row)
    return output
